   105  	 *
   106  	 * @return array
   107  	 */
   108  	public function get_session_data() {
   109  		return $this->has_session() ? (array) $this->get_session( $this->get_customer_id(), array() ) : array();
   110  	}
   111  
   112  	/**
   113  	 * Returns the session.
   114  	 *
   115  	 * @param string $customer_id Customer ID.
